// Parse '!<action> <cardId>' and map action -> destination list ID.
// Point these at YOUR Trello list IDs (or set them as env vars).
const LISTS = {
  done:   $env.TRELLO_LIST_DONE    || 'YOUR_DONE_LIST_ID',
  block:  $env.TRELLO_LIST_BLOCKED || 'YOUR_BLOCKED_LIST_ID',
  review: $env.TRELLO_LIST_REVIEW  || 'YOUR_REVIEW_LIST_ID',
};
const raw = ($json.body?.content ?? $json.content ?? '').trim();
const m = raw.match(/^!(\w+)\s+(\S+)/);
const action = m ? m[1].toLowerCase() : '';
const cardId = m ? m[2] : '';
return { json: { action, cardId, targetList: LISTS[action] || '', known: Boolean(LISTS[action]) && Boolean(cardId) } };
